public boolean isBalanced(TreeNode root) {
    return height(root) != -1;
}

private int height(TreeNode node) {
    if (node == null) return 0;                 // empty subtree
    int left = height(node.left);
    if (left == -1) return -1;                  // short-circuit: left already bad
    int right = height(node.right);
    if (right == -1) return -1;                 // short-circuit: right already bad
    if (Math.abs(left - right) > 1) return -1;  // THIS node is unbalanced
    return 1 + Math.max(left, right);           // balanced → real height
}

